import { useEffect, useMemo, useState } from 'react';
import { Button, Card, DropdownMenu, Icon, SegmentedRadioGroup, Switch, Text } from '@gravity-ui/uikit';
import type { DropdownMenuItem } from '@gravity-ui/uikit';
import { ArrowRotateLeft, ChartLine, Ellipsis, Grip, ListUl, Lock, LockOpen, Plus, TrashBin } from '@gravity-ui/icons';

import { DashboardGrid } from './grid/DashboardGrid';
import type { ItemRenderProps } from './grid/DashboardGrid';
import { type LayoutItem, type PackMode, compact, findFreeSpot } from './grid/layout';
import { RANGES, type RangeKey, getDashboardData } from './data';
import { WIDGETS, WIDGET_GROUPS, type WidgetContext, type WidgetType } from './widgets';
import './styles.css';

const COLS = 12;
const ROW_HEIGHT = 64;
const GAP = 12;
const STORAGE_KEY = 'viz-dashboard/v1';

export interface WidgetItem extends LayoutItem {
    type: WidgetType;
}

interface Saved {
    items: { i: string; type: WidgetType; x: number; y: number; w: number; h: number }[];
    mode: PackMode;
    tableViews: string[];
}

function withLimits(item: Omit<WidgetItem, 'minW' | 'minH' | 'maxH'>): WidgetItem {
    const { minW, minH, maxH } = WIDGETS[item.type].size;
    return { ...item, minW, minH, maxH };
}

const DEFAULT_ITEMS: WidgetItem[] = (
    [
        ['revenue', 'kpi-revenue', 0, 0, 3, 2],
        ['orders', 'kpi-orders', 3, 0, 3, 2],
        ['conversion', 'kpi-conversion', 6, 0, 3, 2],
        ['aov', 'kpi-aov', 9, 0, 3, 2],
        ['trend', 'revenue-trend', 0, 2, 8, 5],
        ['channels', 'channels', 8, 2, 4, 5],
        ['devices', 'devices', 0, 7, 6, 2],
        ['goal', 'goal', 6, 7, 6, 2],
        ['products', 'top-products', 0, 9, 12, 4],
    ] as const
).map(([i, type, x, y, w, h]) => withLimits({ i, type, x, y, w, h }));

function load(): { items: WidgetItem[]; mode: PackMode; tableViews: Set<string> } {
    const fallback = { items: DEFAULT_ITEMS, mode: 'compact' as PackMode, tableViews: new Set<string>() };
    try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (!raw) return fallback;
        const saved = JSON.parse(raw) as Saved;
        const isInt = (v: unknown) => Number.isInteger(v) && (v as number) >= 0;
        const items = saved.items
            .filter((it) => it && it.type in WIDGETS && typeof it.i === 'string')
            .filter((it) => isInt(it.x) && isInt(it.y) && isInt(it.w) && isInt(it.h) && it.w > 0 && it.h > 0)
            .map(withLimits);
        return {
            items,
            mode: saved.mode === 'free' ? 'free' : 'compact',
            tableViews: new Set(Array.isArray(saved.tableViews) ? saved.tableViews : []),
        };
    } catch {
        return fallback;
    }
}

export function App() {
    const initial = useMemo(load, []);
    const [items, setItems] = useState<WidgetItem[]>(initial.items);
    const [mode, setMode] = useState<PackMode>(initial.mode);
    const [tableViews, setTableViews] = useState<Set<string>>(initial.tableViews);
    const [locked, setLocked] = useState(false);
    const [range, setRange] = useState<RangeKey>('30d');
    const [focusId, setFocusId] = useState<string | null>(null);

    const data = useMemo(() => getDashboardData(range), [range]);
    const rangeLabel = RANGES.find((r) => r.value === range)!.label;

    useEffect(() => {
        const saved: Saved = {
            items: items.map(({ i, type, x, y, w, h }) => ({ i, type, x, y, w, h })),
            mode,
            tableViews: [...tableViews].filter((id) => items.some((it) => it.i === id)),
        };
        localStorage.setItem(STORAGE_KEY, JSON.stringify(saved));
    }, [items, mode, tableViews]);

    // Bring a freshly added widget into view and put focus on its handle.
    useEffect(() => {
        if (!focusId) return;
        const el = document.querySelector<HTMLElement>(`[data-widget-id="${focusId}"]`);
        el?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        el?.querySelector<HTMLElement>('.widget__grip')?.focus({ preventScroll: true });
        setFocusId(null);
    }, [focusId]);

    const changeMode = (next: PackMode) => {
        setMode(next);
        if (next === 'compact') setItems((cur) => compact(cur));
    };

    const addWidget = (type: WidgetType) => {
        const { w, h } = WIDGETS[type].size;
        const spot = findFreeSpot(items, w, h, COLS);
        const id = `${type}-${Date.now().toString(36)}`;
        const next = [...items, withLimits({ i: id, type, ...spot })];
        setItems(mode === 'compact' ? compact(next) : next);
        setFocusId(id);
    };

    const removeWidget = (id: string) => {
        const next = items.filter((it) => it.i !== id);
        setItems(mode === 'compact' ? compact(next) : next);
    };

    const toggleTable = (id: string) =>
        setTableViews((cur) => {
            const next = new Set(cur);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });

    const reset = () => {
        setItems(DEFAULT_ITEMS);
        setMode('compact');
        setTableViews(new Set());
    };

    const addMenu: DropdownMenuItem[][] = WIDGET_GROUPS.map((group) =>
        (Object.keys(WIDGETS) as WidgetType[])
            .filter((type) => WIDGETS[type].group === group)
            .map((type) => ({
                text: WIDGETS[type].title,
                iconStart: <Icon data={WIDGETS[type].icon} size={16} />,
                action: () => addWidget(type),
            })),
    );

    const renderItem = (item: WidgetItem, props: ItemRenderProps) => {
        const def = WIDGETS[item.type];
        const asTable = tableViews.has(item.i);
        const ctx: WidgetContext = { data, rangeLabel, asTable };
        const titleId = `widget-title-${item.i}`;
        const menu: DropdownMenuItem[] = [
            ...(def.hasTableView
                ? [
                      {
                          text: asTable ? 'Показать график' : 'Показать таблицей',
                          iconStart: <Icon data={asTable ? ChartLine : ListUl} size={16} />,
                          action: () => toggleTable(item.i),
                      },
                  ]
                : []),
            ...(props.editable
                ? [
                      {
                          text: 'Удалить виджет',
                          theme: 'danger' as const,
                          iconStart: <Icon data={TrashBin} size={16} />,
                          action: () => removeWidget(item.i),
                      },
                  ]
                : []),
        ];

        return (
            <Card
                view={props.dragging ? 'raised' : 'outlined'}
                className={`widget${props.dragging ? ' widget_dragging' : ''}`}
                data-widget-id={item.i}
            >
                <section className="widget__section" aria-labelledby={titleId}>
                    <header
                        className={`widget__header${props.editable ? ' widget__header_draggable' : ''}`}
                        {...props.dragAreaProps}
                    >
                        {props.editable && (
                            <button
                                type="button"
                                className="widget__grip"
                                aria-label={`Переместить или изменить размер: ${def.title}`}
                                {...props.gripProps}
                            >
                                <Icon data={Grip} size={14} />
                            </button>
                        )}
                        <div className="widget__titles">
                            <h2 id={titleId} className="widget__title">
                                {def.title}
                            </h2>
                            {def.subtitle && <div className="widget__subtitle">{def.subtitle(ctx)}</div>}
                        </div>
                        {menu.length > 0 && (
                            <div className="widget__actions" data-no-drag>
                                <DropdownMenu
                                    items={menu}
                                    size="m"
                                    renderSwitcher={(switcher) => (
                                        <Button
                                            {...switcher}
                                            view="flat-secondary"
                                            size="s"
                                            aria-label={`Действия: ${def.title}`}
                                        >
                                            <Icon data={Ellipsis} size={16} />
                                        </Button>
                                    )}
                                />
                            </div>
                        )}
                    </header>
                    <div className="widget__body">{def.render(ctx)}</div>
                </section>
            </Card>
        );
    };

    return (
        <div className="dash viz-root">
            <header className="dash__toolbar">
                <div>
                    <Text as="h1" variant="header-1" className="dash__title">
                        Обзор продаж
                    </Text>
                    <Text color="secondary">
                        {locked
                            ? 'Раскладка зафиксирована'
                            : 'Перетаскивайте виджеты за заголовок, меняйте размер за правый нижний угол'}
                    </Text>
                </div>
                <div className="dash__actions">
                    {!locked && (
                        <>
                            <Switch
                                checked={mode === 'compact'}
                                onUpdate={(on) => changeMode(on ? 'compact' : 'free')}
                                content="Уплотнять вверх"
                                title="Выключите, чтобы оставлять пустые места между виджетами"
                            />
                            <DropdownMenu
                                items={addMenu}
                                renderSwitcher={(switcher) => (
                                    <Button {...switcher} view="action">
                                        <Icon data={Plus} size={16} />
                                        Добавить виджет
                                    </Button>
                                )}
                            />
                            <Button view="outlined" onClick={reset}>
                                <Icon data={ArrowRotateLeft} size={16} />
                                Сбросить
                            </Button>
                        </>
                    )}
                    <Button
                        view={locked ? 'outlined-action' : 'outlined'}
                        selected={locked}
                        onClick={() => setLocked((v) => !v)}
                        aria-pressed={locked}
                    >
                        <Icon data={locked ? Lock : LockOpen} size={16} />
                        {locked ? 'Разблокировать' : 'Зафиксировать'}
                    </Button>
                </div>
            </header>

            <div className="dash__filters" role="group" aria-label="Фильтры">
                <Text color="secondary">Период</Text>
                <SegmentedRadioGroup
                    value={range}
                    onUpdate={(v) => setRange(v as RangeKey)}
                    options={RANGES.map((r) => ({ value: r.value, content: r.label }))}
                    aria-label="Период"
                />
            </div>

            {items.length === 0 ? (
                <div className="dash__empty">
                    <Text variant="subheader-2">На дашборде нет виджетов</Text>
                    <Text color="secondary">Добавьте виджет из каталога или верните стандартную раскладку.</Text>
                    <div className="dash__empty-actions">
                        <DropdownMenu
                            items={addMenu}
                            renderSwitcher={(switcher) => (
                                <Button {...switcher} view="action">
                                    <Icon data={Plus} size={16} />
                                    Добавить виджет
                                </Button>
                            )}
                        />
                        <Button view="outlined" onClick={reset}>
                            Стандартная раскладка
                        </Button>
                    </div>
                </div>
            ) : (
                <DashboardGrid
                    layout={items}
                    cols={COLS}
                    rowHeight={ROW_HEIGHT}
                    gap={GAP}
                    mode={mode}
                    locked={locked}
                    onLayoutChange={setItems}
                    renderItem={renderItem}
                    getItemLabel={(item) => WIDGETS[item.type].title}
                />
            )}
        </div>
    );
}

args.content:
/* ---------------------------------------------------------------- data-viz tokens
 * Reference palette (validated). Light and dark are each selected steps, not a flip.
 */
.viz-root {
    --viz-surface: #fcfcfb;
    --viz-plane: #f9f9f7;
    --viz-ink: #0b0b0b;
    --viz-ink-2: #52514e;
    --viz-muted: #898781;
    --viz-grid: #e1e0d9;
    --viz-axis: #c3c2b7;
    --viz-border: rgba(11, 11, 11, 0.1);
    --viz-series-1: #2a78d6;
    --viz-series-2: #eb6834;
    --viz-series-3: #1baf7a;
    --viz-good-text: #006300;
    --viz-critical: #d03b3b;
    --viz-warning: #fab219;
    --viz-track-accent: #cde2fb;
    --viz-track-warning: #fde9bd;
    --viz-track-danger: #f5d1d1;
}

.g-root_theme_dark .viz-root,
.g-root_theme_dark-hc .viz-root {
    --viz-surface: #1a1a19;
    --viz-plane: #0d0d0d;
    --viz-ink: #f0efec;
    --viz-ink-2: #c3c2b7;
    --viz-muted: #898781;
    --viz-grid: #2c2c2a;
    --viz-axis: #383835;
    --viz-border: rgba(255, 255, 255, 0.1);
    --viz-series-1: #3987e5;
    --viz-series-2: #d95926;
    --viz-series-3: #199e70;
    --viz-good-text: #0ca30c;
    --viz-track-accent: #184f95;
    --viz-track-warning: #5a4210;
    --viz-track-danger: #5a2222;
}

/* ---------------------------------------------------------------- page */

body {
    margin: 0;
}

.dash {
    min-height: 100vh;
    box-sizing: border-box;
    padding: 24px;
    background: var(--viz-plane);
    color: var(--viz-ink);
}

.dash__toolbar {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 16px;
}

.dash__title {
    display: block;
    margin: 0 0 4px;
}

.dash__actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
}

.dash__actions .g-switch {
    margin-right: 8px;
}

.dash__filters {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 16px;
}

.dash__empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    padding: 64px 24px;
    border: 1px dashed var(--g-color-line-generic);
    border-radius: 12px;
    text-align: center;
}

.dash__empty-actions {
    display: flex;
    gap: 8px;
    margin-top: 8px;
}

.visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: -1px;
    padding: 0;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
    border: 0;
}

/* ---------------------------------------------------------------- grid */

.dash-grid {
    position: relative;
    transition: height 0.2s ease;
}

/* Cell guides while editing — so the user sees where things will snap. */
.dash-grid_dragging {
    background-image:
        linear-gradient(to right, transparent calc(var(--grid-step-x) - var(--grid-gap)), var(--viz-plane) 0),
        linear-gradient(to bottom, transparent calc(var(--grid-step-y) - var(--grid-gap)), var(--viz-plane) 0),
        linear-gradient(var(--g-color-base-generic), var(--g-color-base-generic));
    background-size:
        var(--grid-step-x) 100%,
        100% var(--grid-step-y),
        100% 100%;
    border-radius: 8px;
}

.dash-grid__item {
    position: absolute;
    top: 0;
    left: 0;
    box-sizing: border-box;
    transition:
        transform 0.2s ease,
        width 0.2s ease,
        height 0.2s ease;
}

.dash-grid__item_active {
    z-index: 10;
    transition: none;
}

.dash-grid__placeholder {
    position: absolute;
    top: 0;
    left: 0;
    box-sizing: border-box;
    border: 2px dashed var(--g-color-line-brand);
    border-radius: 12px;
    background: var(--g-color-base-selection);
    transition:
        left 0.15s ease,
        top 0.15s ease,
        width 0.15s ease,
        height 0.15s ease;
}

.dash-grid_stacked {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.dash-grid_stacked .dash-grid__item {
    position: relative;
    transform: none !important;
    width: auto !important;
}

.dash-grid__resize {
    position: absolute;
    right: 0;
    bottom: 0;
    width: 20px;
    height: 20px;
    cursor: nwse-resize;
    touch-action: none;
    opacity: 0;
    transition: opacity 0.15s;
}

.dash-grid__resize::after {
    content: '';
    position: absolute;
    right: 5px;
    bottom: 5px;
    width: 8px;
    height: 8px;
    border-right: 2px solid var(--viz-muted);
    border-bottom: 2px solid var(--viz-muted);
    border-bottom-right-radius: 3px;
}

.dash-grid__item:hover .dash-grid__resize,
.dash-grid__item:focus-within .dash-grid__resize,
.dash-grid__item_active .dash-grid__resize {
    opacity: 1;
}

@media (hover: none) {
    .dash-grid__resize {
        opacity: 1;
    }
}

body.dash-dragging,
body.dash-dragging * {
    user-select: none;
}

body.dash-dragging {
    cursor: grabbing;
}

@media (prefers-reduced-motion: reduce) {
    .dash-grid,
    .dash-grid__item,
    .dash-grid__placeholder {
        transition: none;
    }
}

/* ---------------------------------------------------------------- widget chrome */

.widget {
    height: 100%;
    box-sizing: border-box;
    background: var(--viz-surface);
    overflow: hidden;
}

.widget_dragging {
    opacity: 0.92;
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.18);
}

.widget__section {
    display: flex;
    flex-direction: column;
    height: 100%;
}

.widget__header {
    display: flex;
    align-items: flex-start;
    gap: 6px;
    padding: 12px 12px 4px 16px;
    min-height: 32px;
}

.widget__header_draggable {
    cursor: grab;
    touch-action: none;
    user-select: none;
    padding-left: 8px;
}

body.dash-dragging .widget__header_draggable {
    cursor: grabbing;
}

.widget__grip {
    flex: none;
    display: grid;
    place-items: center;
    width: 20px;
    height: 24px;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 4px;
    background: none;
    color: var(--viz-muted);
    cursor: inherit;
}

.widget__grip:hover {
    background: var(--g-color-base-generic-hover);
    color: var(--viz-ink-2);
}

.widget__grip:focus-visible {
    outline: 2px solid var(--g-color-line-focus);
    outline-offset: 0;
}

.widget__titles {
    flex: 1;
    min-width: 0;
    padding-top: 2px;
}

.widget__title {
    margin: 0;
    font-size: 14px;
    font-weight: 600;
    line-height: 20px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.widget__subtitle {
    color: var(--viz-ink-2);
    font-size: 12px;
    line-height: 16px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.widget__actions {
    flex: none;
    cursor: default;
}

.widget__body {
    flex: 1;
    min-height: 0;
    padding: 4px 16px 16px;
    display: flex;
    flex-direction: column;
}

.widget-table {
    flex: 1;
    min-height: 0;
    overflow: auto;
    margin: 0 -16px -16px;
    padding: 0 16px;
}

.num {
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
}

/* ---------------------------------------------------------------- stat tile */

.stat {
    flex: 1;
    min-height: 0;
    display: grid;
    grid-template-columns: auto minmax(64px, 1fr);
    grid-template-rows: auto auto;
    column-gap: 12px;
    align-items: end;
}

.stat__value {
    font-size: 28px;
    font-weight: 600;
    line-height: 34px;
    white-space: nowrap;
}

.stat__delta {
    grid-row: 2;
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 13px;
    line-height: 18px;
    white-space: nowrap;
}

.stat__delta_good {
    color: var(--viz-good-text);
}

.stat__delta_bad {
    color: var(--viz-critical);
}

.stat__period {
    color: var(--viz-muted);
    overflow: hidden;
    text-overflow: ellipsis;
}

.stat .viz-spark {
    grid-column: 2;
    grid-row: 1 / span 2;
    align-self: stretch;
    min-height: 36px;
}

.delta-cell {
    display: inline-flex;
    align-items: center;
    gap: 4px;
}

.delta-cell_good {
    color: var(--viz-good-text);
}

.delta-cell_bad {
    color: var(--viz-critical);
}

/* ---------------------------------------------------------------- goal */

.goal {
    flex: 1;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 8px;
    min-width: 0;
}

.goal__head {
    display: flex;
    align-items: center;
    gap: 12px;
}

.goal__value {
    font-size: 24px;
    font-weight: 600;
    line-height: 28px;
}

.goal__caption {
    white-space: nowrap;
