}

.viz-grid {
    stroke: var(--viz-grid);
    stroke-width: 1;
    shape-rendering: crispEdges;
}

.viz-baseline {
    stroke: var(--viz-axis);
    stroke-width: 1;
    shape-rendering: crispEdges;
}

.viz-axis-text {
    fill: var(--viz-muted);
