/* ---------------------------------------------------------------- page */

body {
    margin: 0;
}

.dash {
    min-height: 100vh;
    box-sizing: border-box;
    padding: 24px;
    background: var(--viz-plane);
    color: var(--viz-ink);
}

.dash__toolbar {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 16px;
}

.dash__title {
    display: block;
    margin: 0 0 4px;
}

.dash__actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
}

.dash__actions .g-switch {
    margin-right: 8px;
}

.dash__filters {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 16px;
}

.dash__empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    padding: 64px 24px;
    border: 1px dashed var(--g-color-line-generic);
    border-radius: 12px;
    text-align: center;
}

.dash__empty-actions {
    display: flex;
    gap: 8px;
    margin-top: 8px;
}

.visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: -1px;
    padding: 0;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
    border: 0;
}

/* ---------------------------------------------------------------- grid */

.dash-grid {
    position: relative;
    transition: height 0.2s ease;
}

/* Cell guides while editing — so the user sees where things will snap. */
.dash-grid_dragging {
    background-image:
        linear-gradient(to right, transparent calc(var(--grid-step-x) - var(--grid-gap)), var(--viz-plane) 0),
        linear-gradient(to bottom, transparent calc(var(--grid-step-y) - var(--grid-gap)), var(--viz-plane) 0),
        linear-gradient(var(--g-color-base-generic), var(--g-color-base-generic));
    background-size:
        var(--grid-step-x) 100%,
        100% var(--grid-step-y),
        100% 100%;
    border-radius: 8px;
}

.dash-grid__item {
    position: absolute;
    top: 0;
    left: 0;
    box-sizing: border-box;
    transition:
        transform 0.2s ease,
        width 0.2s ease,
        height 0.2s ease;
}

.dash-grid__item_active {
    z-index: 10;
    transition: none;
}

.dash-grid__placeholder {
    position: absolute;
    top: 0;
    left: 0;
    box-sizing: border-box;
    border: 2px dashed var(--g-color-line-brand);
    border-radius: 12px;
    background: var(--g-color-base-selection);
    transition:
        left 0.15s ease,
        top 0.15s ease,
        width 0.15s ease,
        height 0.15s ease;
}

.dash-grid_stacked {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.dash-grid_stacked .dash-grid__item {
    position: relative;
    transform: none !important;
    width: auto !important;
}

.dash-grid__resize {
    position: absolute;
    right: 0;
    bottom: 0;
    width: 20px;
    height: 20px;
    cursor: nwse-resize;
    touch-action: none;
    opacity: 0;
    transition: opacity 0.15s;
}

.dash-grid__resize::after {
    content: '';
    position: absolute;
    right: 5px;
    bottom: 5px;
    width: 8px;
    height: 8px;
    border-right: 2px solid var(--viz-muted);
    border-bottom: 2px solid var(--viz-muted);
    border-bottom-right-radius: 3px;
}

.dash-grid__item:hover .dash-grid__resize,
.dash-grid__item:focus-within .dash-grid__resize,
.dash-grid__item_active .dash-grid__resize {
    opacity: 1;
}

@media (hover: none) {
    .dash-grid__resize {
        opacity: 1;
    }
}

body.dash-dragging,
body.dash-dragging * {
    user-select: none;
}

body.dash-dragging {
    cursor: grabbing;
}

@media (prefers-reduced-motion: reduce) {
    .dash-grid,
    .dash-grid__item,
    .dash-grid__placeholder {
        transition: none;
    }
}

/* ---------------------------------------------------------------- widget chrome */

.widget {
    height: 100%;
    box-sizing: border-box;
    background: var(--viz-surface);
    overflow: hidden;
}

.widget_dragging {
    opacity: 0.92;
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.18);
}

.widget__section {
    display: flex;
    flex-direction: column;
    height: 100%;
}

.widget__header {
    display: flex;
    align-items: flex-start;
    gap: 6px;
    padding: 12px 12px 4px 16px;
    min-height: 32px;
}

.widget__header_draggable {
    cursor: grab;
    touch-action: none;
    user-select: none;
    padding-left: 8px;
}

body.dash-dragging .widget__header_draggable {
    cursor: grabbing;
}

.widget__grip {
    flex: none;
    display: grid;
    place-items: center;
    width: 20px;
    height: 24px;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 4px;
    background: none;
    color: var(--viz-muted);
    cursor: inherit;
}

.widget__grip:hover {
    background: var(--g-color-base-generic-hover);
    color: var(--viz-ink-2);
}

.widget__grip:focus-visible {
    outline: 2px solid var(--g-color-line-focus);
    outline-offset: 0;
}

.widget__titles {
    flex: 1;
    min-width: 0;
    padding-top: 2px;
}

.widget__title {
    margin: 0;
    font-size: 14px;
    font-weight: 600;
    line-height: 20px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.widget__subtitle {
    color: var(--viz-ink-2);
    font-size: 12px;
    line-height: 16px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.widget__actions {
    flex: none;
    cursor: default;
}

.widget__body {
    flex: 1;
    min-height: 0;
    padding: 4px 16px 16px;
    display: flex;
    flex-direction: column;
}

.widget-table {
    flex: 1;
    min-height: 0;
    overflow: auto;
    margin: 0 -16px -16px;
    padding: 0 16px;
}

.num {
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
}

/* ---------------------------------------------------------------- stat tile */

.stat {
    flex: 1;
    min-height: 0;
    display: grid;
    grid-template-columns: auto minmax(64px, 1fr);
    grid-template-rows: auto auto;
    column-gap: 12px;
    align-items: end;
}

.stat__value {
    font-size: 28px;
    font-weight: 600;
    line-height: 34px;
    white-space: nowrap;
}

.stat__delta {
    grid-row: 2;
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 13px;
    line-height: 18px;
    white-space: nowrap;
}

.stat__delta_good {
    color: var(--viz-good-text);
}

.stat__delta_bad {
    color: var(--viz-critical);
}

.stat__period {
    color: var(--viz-muted);
    overflow: hidden;
    text-overflow: ellipsis;
}

.stat .viz-spark {
    grid-column: 2;
    grid-row: 1 / span 2;
    align-self: stretch;
    min-height: 36px;
}

.delta-cell {
    display: inline-flex;
    align-items: center;
    gap: 4px;
}

.delta-cell_good {
    color: var(--viz-good-text);
}

.delta-cell_bad {
    color: var(--viz-critical);
}

